(function(){"use strict";app.factory("consolidacionInvService",function(t){const i=t.get("mainService"),o="Inventario/Consolidacion/",e={get:function(t){return i.getData("get",o+"?json="+JSON.stringify(t),null,!0).then(i=>{if("0"===i.code)throw i;if("1"===i.code){let o=JSON.parse(i.payload)||[];if(1===t.tipo){let t=o[0],i=o[1],e=o[2],n=JSON.parse(o[3][0].jsonConfig).find(t=>"AL"==t.codTransaccion);const a=t.reduce((t,i)=>{const o=t.find(t=>t.idEstablecimiento===i.idEstablecimiento&&t.codEstab===i.codEstab);return o?o.puntosEmision.push({idPuntoEmision:i.idPuntoEmision,ptoEmi:i.ptoEmi,defaultPtoEmi:i.defaultPtoEmi}):t.push({idEstablecimiento:i.idEstablecimiento,nombreComercial:i.nombreComercial,codEstab:i.codEstab,defaultEstab:i.defaultEstab,puntosEmision:[{idPuntoEmision:i.idPuntoEmision,ptoEmi:i.ptoEmi,defaultPtoEmi:i.defaultPtoEmi}]}),t},[]);let d=a.map(t=>({...t,bodegas:i.filter(i=>i.idEstablecimiento===t.idEstablecimiento).map(t=>({idBodega:t.idBodega,bodega:t.bodega,defaultBodega:t.defaultBodega}))}));return{estabs:d,subFamilias:e,config:n}}if(2===t.tipo||4===t.tipo)return o[0]}})},post:function(t){return i.getData("post",`${o}`,{data:t},!0)},put:function(t,e){return i.getData("put",`${o}${t}?json=${JSON.stringify(e)}`,null,!0)},delete:function(t){return i.getData("delete",o+t,null,!0)}};return e})})(window.angular);